async complete(context, id, resolution) {
  const notes = resolution.trim();
  if (notes.length === 0) {
    throw new ItTicketError(
      'invalid',
      'RESOLUTION_REQUIRED',
      'Handling notes are required to complete a ticket.',
    );
  }
  const tickets = await scoped('complete', context);
  const existing = await tickets.findOne({ filter: { id } });
  if (!existing) {
    throw new ItTicketError('not_found', 'TICKET_NOT_FOUND');
  }
  if (existing.status !== 'processing') {
    throw new ItTicketError(
      'conflict',
      'TICKET_NOT_PROCESSING',
      'Only a ticket being handled can be completed.',
    );
  }
  const timestamp = now();
  try {
    const { record } = await tickets.updateOne({
      filter: { id, status: 'processing' },
      values: {
        status: 'done',
        resolution: notes,
        completedAt: timestamp,
        updatedAt: timestamp,
      },
    });
    return record;
  } catch (error) {
    if (
      error instanceof RepositoryError &&
      error.code === 'RECORD_NOT_FOUND'
    ) {
      throw new ItTicketError(
        'conflict',
        'TICKET_NOT_PROCESSING',
        'Another handler already finished this ticket.',
